import {createChatState} from './chat-state.js?v=workbench-1';
import {publicProfileHref} from './profile-view.js?v=workbench-1';
import {escapeHtml as h} from './community-model.js';
const photo=(p,online=false)=>'<span class="chat-avatar-wrap"><span class="chat-avatar">'+(p?.avatar_url&&/^https:\/\//.test(p.avatar_url)?'<img alt="" referrerpolicy="no-referrer" src="'+h(p.avatar_url)+'">':h((p?.display_name||p?.username||'?').charAt(0).toUpperCase()))+'</span><span class="chat-online" '+(online?'':'hidden ')+'data-chat-online="'+h(p?.public_id||'')+'" role="img" aria-label="Online" title="Online"></span></span>';
export function mountChat(cloud,{notify=()=>{}}={}){
 const button=document.createElement('button');button.className='message-button chat-toggle';button.type='button';button.setAttribute('aria-label','Messages and updates');button.setAttribute('aria-haspopup','dialog');button.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-2 2v-10A8.5 8.5 0 0 1 10.5 3h2A8.5 8.5 0 0 1 21 11.5Z"/><path d="M7 10h9M7 14h6"/></svg><span class="chat-badge"></span>';
 document.querySelector('.header-tools').append(button);
 const dialog=document.createElement('dialog');dialog.className='chat-dialog';dialog.setAttribute('aria-labelledby','chatTitle');dialog.innerHTML='<header class="chat-top"><h2 id="chatTitle">Messages &amp; updates</h2><button type="button" class="chat-close" aria-label="Close messages">×</button></header><div class="chat-tabs" role="tablist" aria-label="Inbox sections"><button role="tab" aria-selected="true" data-inbox-tab="messages">Messages <span class="messages-count"></span></button><button role="tab" aria-selected="false" data-inbox-tab="updates">Updates <span class="updates-count"></span></button></div><div class="chat-layout"><aside class="chat-people"><p class="chat-caption">Your friends</p><div class="chat-friends"></div><p class="chat-footnote">Follow each other to start a private conversation.</p></aside><section class="chat-thread"><div class="chat-peer"><button type="button" class="chat-back" aria-label="Back to conversations">←</button><div class="chat-peer-label">Choose a friend</div></div><button class="chat-older" type="button" hidden>Load earlier messages</button><div class="chat-messages" role="log" aria-label="Conversation" aria-live="polite"><p class="chat-empty">A good problem is better with a friend.</p></div><p class="chat-status" role="status"></p><form class="chat-compose"><label class="sr-only" for="chatBody">Message</label><textarea id="chatBody" rows="2" maxlength="2000" placeholder="Write a message…" disabled></textarea><button class="button primary" type="submit" disabled>Send</button></form></section></div><section class="chat-updates" hidden><div class="updates-tools"><span>Community updates</span><button type="button" class="updates-read">Mark all read</button></div><div class="updates-items" role="log" aria-label="Problem announcements" aria-live="polite"></div></section>';
 document.body.append(dialog);const $=s=>dialog.querySelector(s),badge=button.querySelector('.chat-badge'),list=$('.chat-friends'),box=$('.chat-messages'),input=$('#chatBody'),send=$('.chat-compose button'),status=$('.chat-status');
 let owner=null,generation=0,peer=null,users=[],messages=[],canMessage=false,reading=false,sending=false,nonce=null,beforeMore=false,activeTab='messages',chatUnread=0,updatesUnread=0,latestUpdate=0,marking=null,readTimer;const signals=createChatState();
 function paintUnread(){const count=chatUnread+updatesUnread;badge.textContent=count?count>99?'99+':String(count):'';button.setAttribute('aria-label',count?'Messages and updates, '+count+' unread':'Messages and updates');$('.messages-count').textContent=chatUnread||'';$('.updates-count').textContent=updatesUnread||'';}
 function unread(n,updates=updatesUnread){chatUnread=Math.max(0,Number(n)||0);updatesUnread=Math.max(0,Number(updates)||0);paintUnread();}
 async function loadUpdates(){if(!owner)return;const ticket=generation,user=owner;$('.updates-items').textContent='Loading updates…';try{const r=await cloud.request('notifications',{},user);if(!valid(ticket,user))return;const items=r.items||[];latestUpdate=items[0]?.id||0;updatesUnread=Number(r.unread??items.filter(x=>x.id>r.lastRead).length);paintUnread();$('.updates-items').innerHTML=items.length?items.map(x=>'<a class="inbox-item '+(x.id>r.lastRead?'unread':'')+'" href="./index.html?problem='+encodeURIComponent(x.problem_id)+'#practice"><small>'+h(x.kind==='new'?'New problem':'Correction')+' · '+h(new Date(x.created_at).toLocaleDateString())+'</small><strong>'+h(x.title)+'</strong><span>'+h(x.message)+'</span></a>').join(''):'<p class="chat-empty">New problems and corrections will arrive here.</p>';}catch(e){if(valid(ticket,user))$('.updates-items').textContent=e.message;}}
 function setTab(tab){activeTab=tab;$('.chat-layout').hidden=tab!=='messages';$('.chat-updates').hidden=tab!=='updates';dialog.querySelectorAll('[data-inbox-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.inboxTab===tab)));if(tab==='updates')loadUpdates();else{loadList();if(peer)refresh();}}
 dialog.querySelectorAll('[data-inbox-tab]').forEach(b=>b.onclick=()=>setTab(b.dataset.inboxTab));
 $('.updates-read').onclick=async()=>{if(!owner)return;const ticket=generation,user=owner;try{await cloud.request('notifications-read',{id:latestUpdate},user);if(valid(ticket,user))loadUpdates();}catch(e){if(valid(ticket,user))$('.updates-items').textContent=e.message;}};
 function clear(){signals.reset();marking=null;clearTimeout(readTimer);peer=null;users=[];messages=[];canMessage=false;reading=false;sending=false;nonce=null;beforeMore=false;input.value='';input.disabled=true;send.disabled=true;list.replaceChildren();box.replaceChildren();$('.chat-peer-label').textContent='Choose a friend';status.textContent='';$('.chat-older').hidden=true;dialog.classList.remove('thread-selected');unread(0,0);$('.updates-items').replaceChildren();latestUpdate=0;activeTab='messages';if(dialog.open)dialog.close();}
 function valid(ticket,user,target){return ticket===generation&&owner===user&&(!target||peer?.public_id===target);}
 function people(){list.innerHTML=users.length?users.map(p=>'<button type="button" data-peer="'+h(p.public_id)+'" class="chat-person '+(p.public_id===peer?.public_id?'selected':'')+'">'+photo(p,signals.online(p.public_id))+'<span><strong>'+h(p.display_name||p.username||'Friend')+'</strong><small>'+h(p.username?'@'+p.username:'Conversation')+'</small></span>'+(Number(p.unread)?'<b>'+Number(p.unread)+'</b>':'')+'</button>').join(''):'<p class="chat-empty">No conversations yet. Find a friend in the top search and follow each other.</p>';list.querySelectorAll('[data-peer]').forEach(b=>b.onclick=()=>select(b.dataset.peer));}
 async function loadList(){if(!owner)return;const ticket=generation,user=owner;try{const r=await cloud.request('chat-list',{},user);if(!valid(ticket,user))return;users=r.users||[];applySignals(r.signals);people();}catch(e){if(valid(ticket,user))list.textContent=e.message;}}
 function paintSignals(){
  dialog.querySelectorAll('[data-chat-online]').forEach(el=>el.hidden=!signals.online(el.dataset.chatOnline));
  dialog.querySelectorAll('[data-chat-receipt]').forEach(el=>{const item=messages.find(m=>m.id===Number(el.dataset.chatReceipt)),seen=item&&signals.seen(item,peer?.public_id);el.classList.toggle('seen',!!seen);el.textContent=seen?'✓✓ Seen':'✓ Sent';});
 }
 function applySignals(value){signals.apply(value);if(dialog.open)paintSignals();}
 function render({scroll=false}={}){const atBottom=box.scrollHeight-box.scrollTop-box.clientHeight<90;box.innerHTML=messages.length?messages.map(m=>'<article data-message-id="'+Number(m.id)+'" data-own="'+String(m.isOwn===true)+'" class="chat-bubble '+(m.isOwn?'own':'')+'"><p>'+h(m.body)+'</p><div class="chat-bubble-meta"><time datetime="'+h(m.created_at)+'">'+h(new Date(m.created_at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}))+'</time>'+(m.isOwn?'<span class="chat-receipt" data-chat-receipt="'+Number(m.id)+'"></span>':'')+'</div></article>').join(''):'<p class="chat-empty">Say hello. Share an idea.</p>';if(scroll||atBottom)box.scrollTop=box.scrollHeight;$('.chat-older').hidden=!beforeMore;input.disabled=!canMessage||sending;send.disabled=!canMessage||sending||!input.value.trim();paintSignals();}
 async function markRead(){
  if(!peer||!dialog.open||activeTab!=='messages'||document.visibilityState!=='visible'||!document.hasFocus()||marking)return;
  const bounds=box.getBoundingClientRect();if(!bounds.height)return;let through=0;
  for(const el of box.querySelectorAll('[data-own="false"]')){const r=el.getBoundingClientRect(),id=Number(el.dataset.messageId),m=messages.find(x=>x.id===id);if(m&&!m.read&&r.bottom>bounds.top&&r.top<bounds.bottom)through=Math.max(through,id);}
  if(!through)return;const ticket=generation,user=owner,target=peer.public_id,request={ticket,target};marking=request;
  try{const r=await cloud.request('chat-read',{target,through},user);if(valid(ticket,user,target)){messages.forEach(m=>{if(!m.isOwn&&m.id<=through)m.read=true;});const p=users.find(p=>p.public_id===target);if(p){p.unread=Number(r.unread)||0;people();}if(Number.isFinite(r.totalUnread)){chatUnread=r.totalUnread;paintUnread();}}}catch{}finally{if(marking===request)marking=null;}
 }
 box.addEventListener('scroll',()=>{clearTimeout(readTimer);readTimer=setTimeout(markRead,160);});
 setInterval(()=>{if(dialog.open&&document.visibilityState==='visible')paintSignals();},1000);
 async function select(target){if(!owner)return;const ticket=++generation,user=owner;peer={public_id:target};marking=null;messages=[];nonce=null;reading=false;sending=false;canMessage=false;input.value='';status.textContent='Loading conversation…';dialog.classList.add('thread-selected');render();people();try{const r=await cloud.request('chat-thread',{target},user);if(!valid(ticket,user,target))return;peer=r.peer;messages=r.messages||[];applySignals(r.signals);canMessage=r.canMessage===true;beforeMore=messages.length===50;$('.chat-peer-label').innerHTML=(peer.username?'<a class="chat-profile-link" href="'+publicProfileHref(peer)+'" aria-label="View '+h(peer.display_name||peer.username)+' profile">'+photo(peer,signals.online(peer.public_id))+'</a>':photo(peer,signals.online(peer.public_id)))+'<span><strong>'+h(peer.display_name||'Friend')+'</strong><small>'+h(peer.username?'@'+peer.username:'Private conversation')+'</small></span>';status.textContent=canMessage?'': 'Both profiles must be discoverable and follow each other to send messages.';render({scroll:true});markRead();people();if(canMessage)input.focus();}catch(e){if(valid(ticket,user,target))status.textContent=e.message;}}
 async function refresh(){if(!peer||!dialog.open||reading||!owner)return;const ticket=generation,user=owner,target=peer.public_id;reading=true;try{let more=true;while(more){const after=messages.at(-1)?.id||0,r=await cloud.request('chat-thread',{target,after},user);if(!valid(ticket,user,target))return;canMessage=r.canMessage===true;applySignals(r.signals);const fresh=(r.messages||[]).filter(m=>!messages.some(old=>old.id===m.id));messages.push(...fresh);messages.sort((a,b)=>a.id-b.id);more=after>0&&r.messages?.length===50&&fresh.length>0;render();}markRead();}catch(e){if(valid(ticket,user,target))status.textContent=e.message;}finally{if(valid(ticket,user,target))reading=false;}}
 $('.chat-older').onclick=async()=>{if(!peer||reading||!messages.length)return;reading=true;const ticket=generation,user=owner,target=peer.public_id,oldHeight=box.scrollHeight;try{const r=await cloud.request('chat-thread',{target,before:messages[0].id},user);if(!valid(ticket,user,target))return;messages=[...(r.messages||[]),...messages];beforeMore=r.messages?.length===50;render();box.scrollTop=box.scrollHeight-oldHeight;}catch(e){if(valid(ticket,user,target))status.textContent=e.message;}finally{if(valid(ticket,user,target))reading=false;}};
 input.oninput=()=>{nonce=null;send.disabled=sending||!canMessage||!input.value.trim();};
 $('.chat-compose').onsubmit=async e=>{e.preventDefault();if(!owner||!peer||!canMessage||sending||!input.value.trim())return;const ticket=generation,user=owner,target=peer.public_id,body=input.value.trim();nonce??=crypto.randomUUID();sending=true;render();status.textContent='Sending…';try{const r=await cloud.request('chat-send',{target,body,nonce},user);if(!valid(ticket,user,target))return;if(!messages.some(m=>m.id===r.message.id))messages.push(r.message);input.value='';nonce=null;status.textContent='';render({scroll:true});loadList();}catch(err){if(valid(ticket,user,target))status.textContent=err.message+' Your message is kept here; try Send again.';}finally{if(valid(ticket,user,target)){sending=false;render();input.focus();}}};
 async function open(target,tab='messages'){if(!owner){notify('Sign in to see messages and community updates.');return;}if(!dialog.open)dialog.showModal();setTab(target?'messages':tab);if(target)await select(target);}
 button.onclick=()=>open(null,updatesUnread&&!chatUnread?'updates':activeTab);$('.chat-close').onclick=()=>dialog.close();$('.chat-back').onclick=()=>dialog.classList.remove('thread-selected');dialog.addEventListener('close',()=>{status.textContent='';});
 return{open,signals:applySignals,openUpdates(){return open(null,'updates');},unread,receiveAnnouncement(item){if(!owner)return;if(dialog.open&&activeTab==='updates'){loadUpdates();return;}notify({display_name:item.kind==='new'?'New problem':'Problem corrected',username:''},{message:item.title,href:'./index.html?problem='+encodeURIComponent(item.problem_id)+'#practice',open:()=>location.assign('./index.html?problem='+encodeURIComponent(item.problem_id)+'#practice')});},setOwner(user){const next=user?.id||null;if(next===owner)return;generation++;owner=next;clear();},resume(){if(dialog.open){if(activeTab==='updates')loadUpdates();else{loadList();refresh();}}},receive(event){if(!owner)return;if(dialog.open&&activeTab==='messages'){loadList();if(peer?.public_id===event.actor?.public_id){refresh();return;}}notify(event.actor,{message:event.preview||'Sent you a message',open:()=>open(event.actor?.public_id)});}};
}
